// تنبيهات الطلبات (صوت الفلوس، إشعار المتصفح، وميض العنوان) · مشتركة بين admin.html وadmin-legacy.html
(function(){
  var SEEN={}, titleT=null, base=document.title, ac=null, on=localStorage.getItem('kh_alerts')!=='0';
  function perm(){ return ('Notification' in window)?Notification.permission:'unsupported'; }
  function bell(){ var b=document.getElementById('bellBtn'); if(!b) return; b.textContent=on?'🔔':'🔕'; b.title=!on?'التنبيهات موقفة (اضغط للتشغيل)':perm()==='granted'?'التنبيهات شغّالة':'التنبيهات شغّالة داخل الصفحة (اضغط للسماح بتنبيهات المتصفح)'; }
  function unlock(){ try{ if(!ac) ac=new (window.AudioContext||window.webkitAudioContext)(); if(ac.state==='suspended') ac.resume(); }catch(e){} }
  /* صوت «فلوس» (طلبها 2026-10-08 «خل الإشعار يكون صوت زي الفلوس»): طقّة درج الكاشير، ثم جرس «تشينغ»، ثم رنّة عملات صغيرة. كله مولّد بـWebAudio بلا ملفات */
  function beepSynth(){ if(!on) return; try{ unlock(); if(!ac) return; var t=ac.currentTime, dest=ac.destination;
    function tone(f,at,len,vol,type){ var o=ac.createOscillator(), g=ac.createGain(); o.type=type||'sine'; o.frequency.value=f; g.gain.setValueAtTime(0.0001,at); g.gain.exponentialRampToValueAtTime(vol,at+0.008); g.gain.exponentialRampToValueAtTime(0.0001,at+len); o.connect(g).connect(dest); o.start(at); o.stop(at+len+0.02); }
    // طقّة الدرج: ضجيج قصير عبر مرشح
    var n=ac.createBufferSource(), buf=ac.createBuffer(1,Math.floor(ac.sampleRate*0.07),ac.sampleRate), d=buf.getChannelData(0); for(var i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length);
    n.buffer=buf; var bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=2600; bp.Q.value=1.2; var ng=ac.createGain(); ng.gain.value=0.35; n.connect(bp).connect(ng).connect(dest); n.start(t); n.stop(t+0.08);
    // الجرس «تشينغ»: نغمتان عاليتان تخمدان ببطء
    tone(2093,t+0.06,0.9,0.22); tone(2637,t+0.06,0.8,0.14); tone(1318,t+0.06,0.5,0.08,'triangle');
    // رنّة العملات: طقطقات صغيرة متتالية
    [0.30,0.37,0.45,0.52,0.62].forEach(function(at,i){ tone(4200+i*350,t+at,0.14,0.10); });
  }catch(e){} }
  /* صوت الطلب الجديد المعتمد (اختارته فادية 2026-10-09): تقليب عملات «Coins handling» (بديل «Clinking coins» بطلبها) من Mixkit (رخصة مجانية تجارية)، مضمّن هنا حتى يشتغل بدون ملفات.
     يُفك ترميزه مرة وحدة عند أول لمسة، ولو فشل يرجع للصوت المولّد beepSynth */
  var CASH_B64='', cashBuf=null, cashTried=false;
  function loadCash(){ if(cashTried||!ac) return; cashTried=true; try{ var bin=atob(CASH_B64), arr=new Uint8Array(bin.length); for(var i=0;i<bin.length;i++) arr[i]=bin.charCodeAt(i); ac.decodeAudioData(arr.buffer).then(function(b){ cashBuf=b; window._khSoundReady=true; }).catch(function(){ cashTried=false; }); }catch(e){ cashTried=false; } }
  function beep(){ if(!on) return; try{ unlock(); if(!ac) return; loadCash(); if(!cashBuf){ beepSynth(); return; } var src=ac.createBufferSource(), g=ac.createGain(); src.buffer=cashBuf; g.gain.value=2.6; var cmp=ac.createDynamicsCompressor(); cmp.threshold.value=-14; cmp.knee.value=10; cmp.ratio.value=6; cmp.attack.value=0.003; cmp.release.value=0.15; src.connect(g).connect(cmp).connect(ac.destination); /* أعلى بوضوح («الصوت وصل لكنه ضعيف») مع ضاغط يمنع التشويش */ src.start(ac.currentTime); }catch(e){ try{ beepSynth(); }catch(x){} } }
  var flashT=null;
  function ding(){ if(!on) return; try{ unlock(); if(!ac) return; var t=ac.currentTime, o=ac.createOscillator(), g=ac.createGain(); o.type='sine'; o.frequency.value=660; g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.12,t+0.01); g.gain.exponentialRampToValueAtTime(0.0001,t+0.5); o.connect(g).connect(ac.destination); o.start(t); o.stop(t+0.55); }catch(e){} }
  function flash(msg){ clearInterval(titleT); var k=0; titleT=setInterval(function(){ document.title=(k++%2)?base:'🔔 '+msg; },900); clearTimeout(flashT); flashT=setTimeout(stopFlash,30000); }
  function stopFlash(){ if(titleT){ clearInterval(titleT); titleT=null; document.title=base; } }
  window.addEventListener('focus',stopFlash); document.addEventListener('visibilitychange',function(){ if(document.visibilityState==='visible') stopFlash(); });
  function notify(title,body){ if(!on||perm()!=='granted') return; try{ var n=new Notification(title,{body:body,tag:'kh-'+Date.now(),lang:'ar',dir:'rtl'}); n.onclick=function(){ window.focus(); n.close(); }; }catch(e){} }
  function when(o){ try{ var d=new Date(o.service_date+'T12:00:00Z'); var days=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت']; var m=+o.start_min||0, h=Math.floor(m/60)%24, mm=m%60; return days[d.getUTCDay()]+' '+d.getUTCDate()+'/'+(d.getUTCMonth()+1)+' · '+(((h+11)%12)+1)+(mm?':'+(mm<10?'0':'')+mm:'')+(h<12?' ص':' م'); }catch(e){ return ''; } }
  window.orderAlert=function(p){
    if(!p||!on) return;
    var o=p.new||{}, ev=p.eventType||p.type;
    if(!o.id) return;
    var city=(o.address&&o.address.city)||'';
    if(ev==='INSERT'){
      if(SEEN['n'+o.id]) return; SEEN['n'+o.id]=1;
      var msg='طلب جديد'+(o.order_no?' رقم '+o.order_no:'')+(o.source==='wa'?' من الواتساب':'')+(city?' · '+city:'')+(o.service_date?' · '+when(o):'');
      beep(); notify('طلب جديد 🔔', msg); flash('طلب جديد'); if(typeof toast==='function') toast('🔔 '+msg);
    } else if(ev==='UPDATE' && o.status==='cancelled'){
      if(SEEN['c'+o.id]) return; SEEN['c'+o.id]=1;
      var m2='طلب'+(o.order_no?' رقم '+o.order_no:'')+' انلغى'+(o.cancelled_by==='customer'?' من العميل':'');
      ding(); notify('إلغاء طلب ❌', m2); if(typeof toast==='function') toast('❌ '+m2);   // إلغاء: نغمة هادئة بدون وميض
    }
  };
  window.alertsToggle=function(){
    unlock();
    if(!on){ on=true; localStorage.setItem('kh_alerts','1'); }
    else if(perm()!=='default'){ on=false; localStorage.setItem('kh_alerts','0'); bell(); if(typeof toast==='function') toast('🔕 التنبيهات موقفة'); return; }
    if(perm()==='default'){ Notification.requestPermission().then(function(){ bell(); if(typeof toast==='function') toast(perm()==='granted'?'🔔 التنبيهات شغّالة مع تنبيهات المتصفح':'🔔 التنبيهات شغّالة داخل الصفحة'); }); }
    else { bell(); if(typeof toast==='function') toast('🔔 التنبيهات شغّالة'); beep(); }
  };
  document.addEventListener('pointerdown',function f(){ unlock(); loadCash(); document.removeEventListener('pointerdown',f); });
  bell();
})();
